<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shift Closing Report</title><style>body{font:15px Arial,sans-serif;color:#222;margin:32px auto;max-width:760px;padding:0 18px}h1{margin-bottom:4px}.muted{color:#666}.row{display:flex;justify-content:space-between;gap:20px;padding:12px 0;border-bottom:1px solid #ddd}.total{font-weight:bold;font-size:18px}@media print{.print{display:none}body{margin:0 auto}}</style></head><body>
<button class="print" onclick="window.print()">Print Report</button><h1>KJM Coffee Shop</h1><h2>Shift Closing Report</h2><p class="muted">Staff: {{ $shift->staff?->name ?? 'Deleted staff' }} · Closed by: {{ $shift->closedBy?->name ?? '—' }} · Shift #{{ $shift->id }}</p><p class="muted">Opened: {{ $shift->opened_at->timezone('Asia/Manila')->format('M j, Y g:i A') }} · Closed: {{ $shift->closed_at?->timezone('Asia/Manila')->format('M j, Y g:i A') ?? 'Open' }}</p><div class="row"><span>Opening cash fund</span><strong>₱{{ number_format($shift->opening_fund, 2) }}</strong></div><div class="row"><span>Cash sales</span><strong>₱{{ number_format($shift->cash_sales, 2) }}</strong></div><div class="row"><span>Cash refunds</span><strong>₱{{ number_format($shift->cash_refunds, 2) }}</strong></div><div class="row"><span>Cash deductions{{ $shift->deduction_reason ? ' · '.$shift->deduction_reason : '' }}</span><strong>₱{{ number_format($shift->cash_deductions, 2) }}</strong></div><div class="row"><span>Expected cash</span><strong>₱{{ number_format($shift->expected_cash, 2) }}</strong></div><div class="row"><span>Actual cash</span><strong>₱{{ number_format($shift->actual_cash, 2) }}</strong></div><div class="row total"><span>Difference</span><strong>₱{{ number_format($shift->cash_difference, 2) }} · {{ ucfirst($shift->reconciliation_status ?? 'open') }}</strong></div><div class="row"><span>Online / QRPH payments (excluded from drawer)</span><strong>₱{{ number_format($shift->online_payments, 2) }}</strong></div></body></html>
